// Package postgres implements ingestion.DataStore, ingestion.ScheduleStore and
// a pipeline store on PostgreSQL via pgx. Queries are generated by sqlc from
// datastore/postgres/queries/*.sql
package postgres

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/galaxy-io/filament"
	"github.com/galaxy-io/filament/datastore/postgres/sqlcgen"
)

// leaseTTL bounds how long a ClaimDue lease is honored before a schedule is
// eligible to be reclaimed
const leaseTTL = 5 * time.Minute

// Store is a Postgres-backed ingestion.DataStore and ingestion.ScheduleStore.
type Store struct {
	pool *pgxpool.Pool
	q    *sqlcgen.Queries
}

// New wraps an already-connected pool. Run Migrate before first use.
func New(pool *pgxpool.Pool) *Store {
	return &Store{pool: pool, q: sqlcgen.New(pool)}
}

var (
	_ ingestion.DataStore     = (*Store)(nil)
	_ ingestion.ScheduleStore = (*Store)(nil)
)

func (s *Store) Name() string { return "postgres" }

// SaveRun upserts the run row and reattaches any carried Resources into
// resource_states, mirroring datastore/memory's SaveRun contract.
func (s *Store) SaveRun(ctx context.Context, r ingestion.RunState) error {
	req, err := json.Marshal(r.Request)
	if err != nil {
		return fmt.Errorf("datastore/postgres: marshal request: %w", err)
	}
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return fmt.Errorf("datastore/postgres: begin: %w", err)
	}
	defer tx.Rollback(ctx)
	q := s.q.WithTx(tx)

	if r.Tenant != "" {
		if err := q.EnsureTenant(ctx, sqlcgen.EnsureTenantParams{TenantID: string(r.Tenant)}); err != nil {
			return fmt.Errorf("datastore/postgres: ensure run tenant: %w", err)
		}
	}

	err = q.SaveRun(ctx, sqlcgen.SaveRunParams{
		RunID:      string(r.Run),
		TenantID:   string(r.Tenant),
		ScheduleID: string(r.ScheduleID),
		Status:     int16(r.Status),
		Request:    req,
		Records:    r.Records,
		Bytes:      r.Bytes,
		StartedAt:  toTimestamptz(nullTime(r.StartedAt)),
		FinishedAt: toTimestamptz(r.FinishedAt),
		Error:      r.Error,
	})
	if err != nil {
		return fmt.Errorf("datastore/postgres: save run: %w", err)
	}

	for _, rs := range r.Resources {
		rs.Run = r.Run
		if rs.Tenant == "" {
			rs.Tenant = r.Tenant
		}
		if err := upsertResource(ctx, q, rs); err != nil {
			return err
		}
	}

	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("datastore/postgres: commit: %w", err)
	}
	return nil
}

// LoadRun returns the run with its current resource states reattached.
func (s *Store) LoadRun(ctx context.Context, id ingestion.RunID) (ingestion.RunState, error) {
	row, err := s.q.LoadRun(ctx, string(id))
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return ingestion.RunState{}, fmt.Errorf("load run %q: %w", id, ingestion.ErrNotFound)
		}
		return ingestion.RunState{}, fmt.Errorf("datastore/postgres: load run: %w", err)
	}

	r, err := runFromLoadRow(row.RunID, row.TenantID, row.ScheduleID, row.Status, row.Request,
		row.Records, row.Bytes, row.StartedAt, row.FinishedAt, row.Error)
	if err != nil {
		return ingestion.RunState{}, err
	}

	resources, err := s.ListResources(ctx, id)
	if err != nil {
		return ingestion.RunState{}, err
	}
	r.Resources = resources
	return r, nil
}

// ListRuns returns runs matching the filter, oldest StartedAt first each with resource states attached.
func (s *Store) ListRuns(ctx context.Context, f ingestion.RunFilter) ([]ingestion.RunState, error) {
	q := `SELECT run_id, tenant_id, coalesce(schedule_id, ''), status, request, records, bytes, started_at, finished_at, coalesce(error, '')
	      FROM runs WHERE 1=1`
	args := []any{}
	arg := func(v any) string {
		args = append(args, v)
		return fmt.Sprintf("$%d", len(args))
	}
	if f.Tenant != "" {
		q += " AND tenant_id = " + arg(string(f.Tenant))
	}
	if f.Schedule != "" {
		q += " AND schedule_id = " + arg(string(f.Schedule))
	}
	if f.Source != "" {
		q += " AND (source_provider = " + arg(f.Source) + " OR request->'Source'->>'ConfigRef' = " + arg(f.Source) + ")"
	}
	if !f.Since.IsZero() {
		q += " AND started_at >= " + arg(f.Since)
	}
	if len(f.Status) > 0 {
		statuses := make([]int, len(f.Status))
		for i, st := range f.Status {
			statuses[i] = int(st)
		}
		q += " AND status = ANY(" + arg(statuses) + ")"
	}
	q += " ORDER BY started_at ASC, run_id ASC"
	if f.Limit > 0 {
		q += " LIMIT " + arg(f.Limit)
	}

	rows, err := s.pool.Query(ctx, q, args...)
	if err != nil {
		return nil, fmt.Errorf("datastore/postgres: list runs: %w", err)
	}
	defer rows.Close()

	var out []ingestion.RunState
	var ids []ingestion.RunID
	for rows.Next() {
		var (
			runID, tenant, scheduleID, errMsg string
			status                            int
			req                               []byte
			records, bytes                    int64
			started                           *time.Time
			finished                          *time.Time
		)
		if err := rows.Scan(&runID, &tenant, &scheduleID, &status, &req, &records, &bytes, &started, &finished, &errMsg); err != nil {
			return nil, fmt.Errorf("datastore/postgres: scan run: %w", err)
		}
		r, err := runFromRaw(runID, tenant, scheduleID, status, req, records, bytes, started, finished, errMsg)
		if err != nil {
			return nil, err
		}
		out = append(out, r)
		ids = append(ids, r.Run)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("datastore/postgres: list runs: %w", err)
	}

	for i, id := range ids {
		resources, err := s.ListResources(ctx, id)
		if err != nil {
			return nil, err
		}
		out[i].Resources = resources
	}
	return out, nil
}

func runFromLoadRow(runID, tenant, scheduleID string, status int16, req []byte, records, bytes int64, started, finished pgtype.Timestamptz, errMsg string) (ingestion.RunState, error) {
	return runFromRaw(runID, tenant, scheduleID, int(status), req, records, bytes, fromTimestamptz(started), fromTimestamptz(finished), errMsg)
}

func runFromRaw(runID, tenant, scheduleID string, status int, req []byte, records, bytes int64, started, finished *time.Time, errMsg string) (ingestion.RunState, error) {
	var r ingestion.RunState
	r.Run = ingestion.RunID(runID)
	r.Tenant = ingestion.TenantID(tenant)
	r.ScheduleID = ingestion.ScheduleID(scheduleID)
	r.Status = ingestion.RunStatus(status)
	r.Records = records
	r.Bytes = bytes
	r.Error = errMsg
	if started != nil {
		r.StartedAt = *started
	}
	r.FinishedAt = finished
	if err := json.Unmarshal(req, &r.Request); err != nil {
		return ingestion.RunState{}, fmt.Errorf("datastore/postgres: unmarshal request: %w", err)
	}
	return r, nil
}

func nullTime(t time.Time) *time.Time {
	if t.IsZero() {
		return nil
	}
	return &t
}

func toTimestamptz(t *time.Time) pgtype.Timestamptz {
	if t == nil {
		return pgtype.Timestamptz{Valid: false}
	}
	return pgtype.Timestamptz{Time: *t, Valid: true}
}

func fromTimestamptz(t pgtype.Timestamptz) *time.Time {
	if !t.Valid {
		return nil
	}
	tt := t.Time
	return &tt
}

func (s *Store) UpsertResource(ctx context.Context, rs ingestion.ResourceState) error {
	return upsertResource(ctx, s.q, rs)
}

func upsertResource(ctx context.Context, q *sqlcgen.Queries, rs ingestion.ResourceState) error {
	err := q.UpsertResource(ctx, sqlcgen.UpsertResourceParams{
		RunID:        string(rs.Run),
		ResourceName: rs.Resource,
		TenantID:     string(rs.Tenant),
		Enabled:      rs.Enabled,
		Status:       int16(rs.Status),
		Records:      rs.Records,
		Bytes:        rs.Bytes,
		Error:        rs.Error,
	})
	if err != nil {
		return fmt.Errorf("datastore/postgres: upsert resource: %w", err)
	}
	return nil
}

func (s *Store) ListResources(ctx context.Context, id ingestion.RunID) ([]ingestion.ResourceState, error) {
	rows, err := s.q.ListResources(ctx, string(id))
	if err != nil {
		return nil, fmt.Errorf("datastore/postgres: list resources: %w", err)
	}
	out := make([]ingestion.ResourceState, len(rows))
	for i, row := range rows {
		out[i] = ingestion.ResourceState{
			Run:      ingestion.RunID(row.RunID),
			Resource: row.ResourceName,
			Tenant:   ingestion.TenantID(row.TenantID),
			Enabled:  row.Enabled,
			Status:   ingestion.RunStatus(row.Status),
			Records:  row.Records,
			Bytes:    row.Bytes,
			Error:    row.Error,
		}
	}
	return out, nil
}

func (s *Store) SaveCheckpoint(ctx context.Context, id ingestion.RunID, cp ingestion.Checkpoint) error {
	cursor, err := json.Marshal(cp.Raw())
	if err != nil {
		return fmt.Errorf("datastore/postgres: marshal checkpoint: %w", err)
	}
	err = s.q.SaveCheckpoint(ctx, sqlcgen.SaveCheckpointParams{
		RunID:        string(id),
		ResourceName: cp.Resource(),
		Cursor:       cursor,
	})
	if err != nil {
		return fmt.Errorf("datastore/postgres: save checkpoint: %w", err)
	}
	return nil
}

func (s *Store) LoadCheckpoint(ctx context.Context, id ingestion.RunID, resource string) (ingestion.Checkpoint, error) {
	cursor, err := s.q.LoadCheckpoint(ctx, sqlcgen.LoadCheckpointParams{RunID: string(id), ResourceName: resource})
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, fmt.Errorf("load checkpoint %q/%q: %w", id, resource, ingestion.ErrNotFound)
		}
		return nil, fmt.Errorf("datastore/postgres: load checkpoint: %w", err)
	}
	var raw map[string]any
	if err := json.Unmarshal(cursor, &raw); err != nil {
		return nil, fmt.Errorf("datastore/postgres: unmarshal checkpoint: %w", err)
	}
	return &ingestion.CheckpointData{ResourceName: resource, Cursor: raw}, nil
}

// DedupSeen reports whether seq has already been applied for (tenant, run),
// advancing the run's high-water mark on the first call to see it. This
// relies on the tracker processing each run's facts through
// one sequential pump, so seq only ever increases per run
func (s *Store) DedupSeen(ctx context.Context, tenant string, run ingestion.RunID, seq uint64) (bool, error) {
	if tenant != "" {
		if err := s.EnsureTenant(ctx, ingestion.TenantID(tenant), ""); err != nil {
			return false, fmt.Errorf("datastore/postgres: ensure dedup tenant: %w", err)
		}
	}
	_, err := s.q.AdvanceDedupSeen(ctx, sqlcgen.AdvanceDedupSeenParams{
		TenantID: tenant,
		RunID:    string(run),
		Seq:      int64(seq),
	})
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return true, nil
		}
		return false, fmt.Errorf("datastore/postgres: dedup seen: %w", err)
	}
	return false, nil
}

func (s *Store) SaveSchedule(ctx context.Context, st ingestion.ScheduleState) error {
	req, err := json.Marshal(st.Spec.Request)
	if err != nil {
		return fmt.Errorf("datastore/postgres: marshal schedule request: %w", err)
	}
	if st.Spec.Tenant != "" {
		if err := s.EnsureTenant(ctx, st.Spec.Tenant, ""); err != nil {
			return fmt.Errorf("datastore/postgres: ensure schedule tenant: %w", err)
		}
	}
	err = s.q.SaveSchedule(ctx, sqlcgen.SaveScheduleParams{
		ScheduleID:    string(st.ID),
		TenantID:      string(st.Spec.Tenant),
		Name:          toText(st.Spec.Name),
		CronExpr:      st.Spec.Cron,
		Timezone:      st.Spec.Timezone,
		JitterMs:      st.Spec.Jitter.Milliseconds(),
		OverlapPolicy: int16(st.Spec.Overlap),
		CatchupPolicy: int16(st.Spec.Catchup),
		Request:       req,
		Enabled:       st.Enabled,
		LastFiredAt:   toTimestamptz(st.LastFired),
		NextFireAt:    toTimestamptz(st.NextFire),
		LastRunID:     string(st.LastRun),
		LastRunStatus: pgtype.Int2{Int16: int16(st.LastStatus), Valid: true},
		CreatedAt:     toTimestamptz(nullTime(st.CreatedAt)),
	})
	if err != nil {
		return fmt.Errorf("datastore/postgres: save schedule: %w", err)
	}
	return nil
}

func (s *Store) LoadSchedule(ctx context.Context, id ingestion.ScheduleID) (ingestion.ScheduleState, error) {
	row, err := s.q.LoadSchedule(ctx, string(id))
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return ingestion.ScheduleState{}, fmt.Errorf("load schedule %q: %w", id, ingestion.ErrNotFound)
		}
		return ingestion.ScheduleState{}, fmt.Errorf("datastore/postgres: load schedule: %w", err)
	}
	return scheduleFromLoadRow(row.ScheduleID, row.TenantID, row.Name, row.CronExpr, row.Timezone, row.JitterMs,
		row.OverlapPolicy, row.CatchupPolicy, row.Request, row.Enabled, row.LastFiredAt, row.NextFireAt,
		row.LastRunID, row.LastRunStatus, row.CreatedAt)
}

func (s *Store) ListSchedules(ctx context.Context, f ingestion.ScheduleFilter) ([]ingestion.ScheduleState, error) {
	var filterEnabled pgtype.Bool
	if f.Enabled != nil {
		filterEnabled = pgtype.Bool{Bool: *f.Enabled, Valid: true}
	}
	rows, err := s.q.ListSchedules(ctx, sqlcgen.ListSchedulesParams{
		TenantID:      string(f.Tenant),
		FilterEnabled: filterEnabled,
		Lim:           int32(f.Limit),
	})
	if err != nil {
		return nil, fmt.Errorf("datastore/postgres: list schedules: %w", err)
	}
	out := make([]ingestion.ScheduleState, len(rows))
	for i, row := range rows {
		st, err := scheduleFromLoadRow(row.ScheduleID, row.TenantID, row.Name, row.CronExpr, row.Timezone, row.JitterMs,
			row.OverlapPolicy, row.CatchupPolicy, row.Request, row.Enabled, row.LastFiredAt, row.NextFireAt,
			row.LastRunID, row.LastRunStatus, row.CreatedAt)
		if err != nil {
			return nil, err
		}
		out[i] = st
	}
	return out, nil
}

func (s *Store) DeleteSchedule(ctx context.Context, id ingestion.ScheduleID) error {
	if err := s.q.DeleteSchedule(ctx, string(id)); err != nil {
		return fmt.Errorf("datastore/postgres: delete schedule: %w", err)
	}
	return nil
}

// ClaimDue leases up to limit, enabled schedules not
// currently under an unexpired lease, and stamps them claimed_at = now() in
// the same transaction as the SELECT ... FOR UPDATE SKIP LOCKED so a second
// scheduler replica racing this call cannot pick up the same row: it will
// either block-and-skip (SKIP LOCKED) or see claimed_at within leaseTTL and
// filter it out. The lease is released by the next SaveSchedule call
// or expires after leaseTTL if the scheduler that claimed it crashes
// before calling SaveSchedule.
func (s *Store) ClaimDue(ctx context.Context, now time.Time, limit int) ([]ingestion.ScheduleState, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, fmt.Errorf("datastore/postgres: begin: %w", err)
	}
	defer tx.Rollback(ctx)
	q := s.q.WithTx(tx)

	rows, err := q.ClaimDue(ctx, sqlcgen.ClaimDueParams{
		Now:         pgtype.Timestamptz{Time: now, Valid: true},
		LeaseCutoff: pgtype.Timestamptz{Time: now.Add(-leaseTTL), Valid: true},
		Lim:         int32(limit),
	})
	if err != nil {
		return nil, fmt.Errorf("datastore/postgres: claim due: %w", err)
	}

	out := make([]ingestion.ScheduleState, len(rows))
	ids := make([]string, len(rows))
	for i, row := range rows {
		st, err := scheduleFromLoadRow(row.ScheduleID, row.TenantID, row.Name, row.CronExpr, row.Timezone, row.JitterMs,
			row.OverlapPolicy, row.CatchupPolicy, row.Request, row.Enabled, row.LastFiredAt, row.NextFireAt,
			row.LastRunID, row.LastRunStatus, row.CreatedAt)
		if err != nil {
			return nil, err
		}
		out[i] = st
		ids[i] = row.ScheduleID
	}

	if len(ids) > 0 {
		err := q.LeaseSchedules(ctx, sqlcgen.LeaseSchedulesParams{
			ClaimedAt:   pgtype.Timestamptz{Time: now, Valid: true},
			ScheduleIds: ids,
		})
		if err != nil {
			return nil, fmt.Errorf("datastore/postgres: lease claimed schedules: %w", err)
		}
	}
	if err := tx.Commit(ctx); err != nil {
		return nil, fmt.Errorf("datastore/postgres: commit claim: %w", err)
	}
	return out, nil
}

func (s *Store) MarkFired(ctx context.Context, id ingestion.ScheduleID, at time.Time) error {
	err := s.q.MarkFired(ctx, sqlcgen.MarkFiredParams{
		FiredAt:    pgtype.Timestamptz{Time: at, Valid: true},
		ScheduleID: string(id),
	})
	if err != nil {
		return fmt.Errorf("datastore/postgres: mark fired: %w", err)
	}
	return nil
}

func toText(s string) pgtype.Text {
	if s == "" {
		return pgtype.Text{}
	}
	return pgtype.Text{String: s, Valid: true}
}

func scheduleFromLoadRow(id, tenant string, name pgtype.Text, cronExpr, tz string, jitterMs int64,
	overlap, catchup int16, req []byte, enabled bool, lastFired, nextFire pgtype.Timestamptz,
	lastRun string, lastStatus pgtype.Int2, createdAt pgtype.Timestamptz) (ingestion.ScheduleState, error) {

	var request ingestion.RunRequest
	if err := json.Unmarshal(req, &request); err != nil {
		return ingestion.ScheduleState{}, fmt.Errorf("datastore/postgres: unmarshal schedule request: %w", err)
	}
	var created time.Time
	if createdAt.Valid {
		created = createdAt.Time
	}
	return ingestion.ScheduleState{
		ID: ingestion.ScheduleID(id),
		Spec: ingestion.ScheduleSpec{
			Tenant:   ingestion.TenantID(tenant),
			Name:     name.String,
			Cron:     cronExpr,
			Timezone: tz,
			Jitter:   time.Duration(jitterMs) * time.Millisecond,
			Overlap:  ingestion.OverlapPolicy(overlap),
			Catchup:  ingestion.CatchupPolicy(catchup),
			Request:  request,
			Enabled:  enabled,
		},
		Enabled:    enabled,
		LastFired:  fromTimestamptz(lastFired),
		NextFire:   fromTimestamptz(nextFire),
		LastRun:    ingestion.RunID(lastRun),
		LastStatus: ingestion.RunStatus(lastStatus.Int16),
		CreatedAt:  created,
	}, nil
}
